import { ExpreeImageTool, IImageEditorParam } from './ExpreeImageTool';
export class Demo510ImageTool {
    expreeImageTool: ExpreeImageTool;
    static Init(id: string) {
        const parma: IImageEditorParam = {
            id: id,
            // ui: true,
            colorCover: '#ff0000',
        };
        const n = new Demo510ImageTool(parma);
        n.Dummy();
    }
    constructor(parma: IImageEditorParam) {
        this.expreeImageTool = new ExpreeImageTool(parma);
    }
    public Dummy() {
        // TODO
    }
}


export class Solution {
    public divHost: HTMLElement;

    constructor(id: string ) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        Demo510ImageTool.Init(id)
    }
    public destroy() {
        if (this.divHost) {
            try {
                while (this.divHost.firstChild) {
                    this.divHost.removeChild(this.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}